CREATE TABLE IF NOT EXISTS app_role (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50), code VARCHAR(30), permissions VARCHAR(500));
CREATE TABLE IF NOT EXISTS store (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), address VARCHAR(200), contact VARCHAR(50), phone VARCHAR(30));
CREATE TABLE IF NOT EXISTS warehouse (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), store_id BIGINT, address VARCHAR(200));
CREATE TABLE IF NOT EXISTS app_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE, password_hash VARCHAR(100), name VARCHAR(50), role_id BIGINT, store_id BIGINT, active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS supplier (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), contact VARCHAR(50), phone VARCHAR(30), address VARCHAR(200));
CREATE TABLE IF NOT EXISTS category (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) UNIQUE);
CREATE TABLE IF NOT EXISTS ingredient (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), category_id BIGINT, specification VARCHAR(100), unit VARCHAR(20), price DECIMAL(12,2), shelf_days INT, min_stock DECIMAL(12,3), max_stock DECIMAL(12,3));
CREATE TABLE IF NOT EXISTS stock_batch (id BIGINT AUTO_INCREMENT PRIMARY KEY, ingredient_id BIGINT, warehouse_id BIGINT, supplier_id BIGINT, batch_no VARCHAR(80), expiry_date DATE, quantity DECIMAL(12,3), unit_cost DECIMAL(12,2));
CREATE TABLE IF NOT EXISTS movement (id BIGINT AUTO_INCREMENT PRIMARY KEY, batch_id BIGINT, kind VARCHAR(20), quantity DECIMAL(12,3), reference_no VARCHAR(80), actor_id BIGINT, store_id BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS requisition (id BIGINT AUTO_INCREMENT PRIMARY KEY, number VARCHAR(60) UNIQUE, store_id BIGINT, warehouse_id BIGINT, status VARCHAR(30), note VARCHAR(500), created_by BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS requisition_line (id BIGINT AUTO_INCREMENT PRIMARY KEY, requisition_id BIGINT, ingredient_id BIGINT, quantity DECIMAL(12,3));
CREATE TABLE IF NOT EXISTS purchase_order (id BIGINT AUTO_INCREMENT PRIMARY KEY, number VARCHAR(60) UNIQUE, supplier_id BIGINT, warehouse_id BIGINT, status VARCHAR(30), total DECIMAL(12,2), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT, action VARCHAR(100), detail VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
